        int[] c = new int[10];
        for (int i = 0; i < v.length; i++) {
            c[Integer.parseInt(v[i].charAt(index)+"")] += 1;
        }

        // cumulativa
        for (int i = 1; i < c.length; i++)
            c[i] += c[i-1];

        String[] b = new String[v.length];
        for (int i = v.length - 1; i >= 0; i--) {
            b[c[Integer.parseInt(v[i].charAt(index)+"")] - 1] = v[i];
            c[Integer.parseInt(v[i].charAt(index)+"")] -= 1;
        }

