Aqui está minha resposta ao prompt:

O problema pede para escrever um programa que determine se um grafo não direcionado e não ponderado é uma árvore. Uma árvore é um grafo conectado sem ciclos. O programa deve ler o número de nós (N) e o número de arestas (M) do grafo. Em seguida, ele deve ler as arestas, que são representadas por pares de nós. O programa deve imprimir "True" se o grafo for uma árvore e "False" caso contrário.

Para determinar se um grafo é uma árvore, podemos verificar duas condições:
1. O número de arestas deve ser igual a N-1.
2. O grafo deve ser conectado e não deve conter ciclos.

Podemos usar a busca em profundidade (DFS) para verificar se o grafo é conectado e não contém ciclos. A DFS começa em um nó e explora o grafo o máximo possível ao longo de cada ramo antes de retroceder. Durante a DFS, podemos manter um conjunto de nós visitados. Se encontrarmos uma aresta que leva a um nó já visitado (que não seja o pai do nó atual), então o grafo contém um ciclo. Se a DFS visitar todos os nós no grafo, então o grafo é conectado.

Aqui está um exemplo de como o programa pode ser implementado em Java:

```java
import java.util.*;
import java.lang.*;
import java.io.*;

class Solution {
    public static void main(String[] args) throws java.lang.Exception {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt();
        int M = in.nextInt();

        if (M != N - 1) {
            System.out.println("False");
            return;
        }

        AdjacencyList adj = new AdjacencyList(N);
        for (int i = 0; i < M; i++) {
            int u = in.nextInt();
            int v = in.nextInt();
            adj.addEdge(u, v);
        }

        if (!adj.isTree()) {
            System.out.println("False");
        } else {
            System.out.println("True");
        }
    }
}

class Edge {
    private int startNode;
    private int endNode;
    private int weight;

    public Edge(int startNode, int endNode, int weight) {
        this.startNode = startNode;
        this.endNode = endNode;
        this.weight = weight;
    }

    public int getStartNode() {
        return startNode;
    }

    public int getEndNode() {
        return endNode;
    }

    public int getWeight() {
        return weight;
    }
}

class AdjacencyList {
    private List<Edge>[] adjacencyList;
    private boolean isDirected;
    private Boolean[] visited;
    private int reachableFromZero;
    private boolean hasCycle;
    private int numberOfEdges;

    public AdjacencyList(int vertices) {
        adjacencyList = new ArrayList[vertices];
        this.isDirected = false;
        this.visited = new Boolean[vertices];
        this.hasCycle = false;
        this.reachableFromZero = 0;
        this.numberOfEdges = 0;

        for (int i = 0; i < adjacencyList.length; i++) {
            adjacencyList[i] = new ArrayList<>();
            visited[i] = false;
        }
    }

    public void addEdge(int startVertex, int endVertex) {
        adjacencyList[startVertex].add(new Edge(startVertex, endVertex, 1));
        adjacencyList[endVertex].add(new Edge(endVertex, startVertex, 1));
        this.numberOfEdges++;
    }

    public int getNumberOfVertices() {
        return adjacencyList.length;
    }

    public int getNumberOfEdges() {
        return numberOfEdges;
    }

    public List<Edge> getEdgesFromVertex(int startVertex) {
        return new ArrayList<>(adjacencyList[startVertex]);
    }

    public void dfs(int node, int par) {
        this.visited[node] = true;
        this.reachableFromZero++;

        for (Edge edge : getEdgesFromVertex(node)) {
            int neighbor = edge.getEndNode();
            if (!visited[neighbor]) {
                dfs(neighbor, node);
            } else if (neighbor != par) {
                this.hasCycle = true;
                return;
            }
        }
    }

    public boolean isTree() {
        if (getNumberOfEdges() != getNumberOfVertices() - 1) {
            return false;
        }

        for (int i = 0; i < getNumberOfVertices(); i++) {
            visited[i] = false;
        }

        dfs(0, -1);

        return this.reachableFromZero == getNumberOfVertices() && !this.hasCycle;
    }
}
